<div class="topline"><span><?= e(t('PROGRESS WITH A PURPOSE')) ?></span><span><?= e(t('Small steps. Meaningful direction.')) ?></span></div><header class="page-header"><div><h1><?= e(t('Give your ambitions a next step.')) ?></h1><p class="muted"><?= e(t('Short-term goals, long-term goals and the milestones between.')) ?></p></div></header><?php require ROOT.'/app/Core/views/notices.php'; ?>
<div class="two-col"><section class="card"><h2><?= e(t('Your personal goals')) ?></h2><?php if (!$goals): ?><div class="empty"><h3><?= e(t('No data yet.')) ?></h3><p><?= e(t('Create a goal for something that matters to you.')) ?></p></div><?php else: foreach ($goals as $g): $pct=GrowthService::progress($g); ?><article class="lesson-entry"><div class="section-heading"><a href="/growth/<?= e($g['id']) ?>"><strong><?= e($g['title']) ?></strong></a><span class="badge"><?= e($g['status']) ?></span></div><small><?= e(GrowthService::CATEGORIES[$g['category']]) ?> · <?= $g['horizon']==='long' ? t('Long term') : t('Short term') ?><?= $g['due_date'] ? ' · Due '.e($g['due_date']) : '' ?></small><?= progress_donut((float)$pct,'Goal progress',$g['done_count'].' of '.$g['step_count'].' steps complete',true) ?><?php if ($g['prerequisite']): ?><small><?= e(t('Prerequisite:')) ?> <?= e($g['prerequisite']) ?> · <?= e($g['prerequisite_status']) ?></small><?php endif; ?></article><?php endforeach; endif; ?><p class="footnote"><?= e(t('Financial goals linked to asset values remain in Investments. These goals track your actionable progress.')) ?></p></section><section class="card" id="new-goal"><h2><?= e(t('Create a personal goal')) ?></h2><?php require __DIR__.'/goal-form.php'; ?></section></div>
